# Set only the actual hostname read from this newly allocated own Colab CPU/high-RAM runtime.
# Prior validation348D runtime must first be closed with separate Manage sessions readback.
OWNED_RUNTIME_NODE = ''
import os, sys, platform, base64, hashlib, json
from pathlib import Path, PurePosixPath
ROOT=Path('/content/ui-validation348E')
def require(ok,message):
    if not ok:raise ValueError(message)
def digest(raw):return hashlib.sha256(raw).hexdigest()
require(os.name=='posix' and Path('/content').is_dir(),'Own Colab Linux only')
require(isinstance(OWNED_RUNTIME_NODE,str) and OWNED_RUNTIME_NODE and platform.node()==OWNED_RUNTIME_NODE,'Set actual owned runtime hostname')
require(not ROOT.exists() and not ROOT.is_symlink(),'Fresh348E destination; never overwrite prior results')
require(not Path('/content').is_symlink(),'No symlink parent')
MANIFEST_SHA256 = 'e9ce87700900428da2ef1817ea186d00a32ec4ce4202b926b882439bb2975c62'
PAYLOAD = json.loads(r'''{"SOURCE-INPUTS348.json":"","RUNNER-HASHES348E.json":"","historical348D/run_preflight348D.py":"","validate348E_actual_colab.py":"","historical348D/RUNNER-HASHES348D.json":"","historical348D/build348.py":"","historical348D/SOURCE-INPUTS348.json":"","validate_return348E.py":"","historical348D/mark_artifact_operation_started.mjs":"","actual-production348D-report.json":"","test_validate_return348E.py":"","run_preflight348E.py":"","historical348D/validate_return348D.py":"","historical348D/test_validate_return348D.py":"","historical348D/ui_launch348D.py":"","INPUT-CHUNKS348E.json":"","historical348D/validate348_ui_actual_colab.py":""}''')
manifest_raw=base64.b64decode(PAYLOAD['RUNNER-HASHES348E.json'],validate=True)
require(digest(manifest_raw)==MANIFEST_SHA256,'Frozen current runner manifest')
rows=json.loads(manifest_raw)
names=[r['path'] for r in rows]
require(len(names)==len(set(names)) and set(PAYLOAD)==set(names)|{'RUNNER-HASHES348E.json'},'Exact runtime payload inventory')
raw_files={}
for row in rows:
    name=row['path'];parts=PurePosixPath(name).parts
    require(isinstance(name,str) and name and chr(92) not in name and not PurePosixPath(name).is_absolute() and all(p not in ('','.','..') for p in name.split('/')),'Contained runtime payload path')
    raw=base64.b64decode(PAYLOAD[name],validate=True)
    require(type(row['bytes']) is int and len(raw)==row['bytes'] and digest(raw)==row['sha256'],'Exact embedded payload bytes')
    raw_files[name]=raw
raw_files['RUNNER-HASHES348E.json']=manifest_raw
ROOT.mkdir()
for name,raw in raw_files.items():
    path=ROOT/name;path.parent.mkdir(parents=True,exist_ok=True)
    require(path.resolve().is_relative_to(ROOT) and not path.is_symlink(),'Contained exclusive file')
    with path.open('xb') as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
    require(path.read_bytes()==raw,'Runtime materialization readback')
(ROOT/'input-parts').mkdir();(ROOT/'transport-receipts').mkdir()
print(json.dumps({'hostname':platform.node(),'runtime_payloads':len(raw_files),'runner_manifest_sha256':digest(manifest_raw),'scope':'Materialization only; no validation or PDF production result'}))
